 legacy=facts;legacy.existingFoodFamilyMask=4;Check(use(3,empty,214,legacy).error().code==14 && use(4,empty,215,legacy).has_value(),"server-observed winter affect blocks only winter native food");legacy.existingFoodFamilyMask=8;Check(use(4,empty,216,legacy).error().code==14,"server-observed festival affect blocks its native duplicate");
