 auto bad=source;std::ranges::find(bad.timedEffects,40002u,&TimedEffectProfile::id)->conflictBonus=BonusId::Strength;Check(!BuildItemCatalog(bad),"selected fish conflict must belong to the real bundle");bad=source;std::ranges::find(bad.timedEffectGroups,40000u,&TimedEffectGroup::id)->family=TimedEffectFamily::Generic;Check(!BuildItemCatalog(bad),"generic groups cannot claim fish point admission");bad=source;std::ranges::find(bad.timedEffectGroups,40003u,&TimedEffectGroup::id)->reapply=TimedEffectReapply::Replace;Check(!BuildItemCatalog(bad),"original seasonal families cannot replace active effects");
